(()=>{
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>new Date(value).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'})+' IST';
const pending=booking=>(booking.cancellations||[]).find(item=>item.status==='pending');
window.GoRideCancellations={pending,render(booking,owner=false){
const history=booking.cancellations||[],active=['requested','confirmed'].includes(booking.status);
if(!history.length&&!active)return '';
return `<section class="cancellation-panel" aria-label="Cancellation requests"><div class="cancellation-heading"><h3>Cancellation requests</h3>${pending(booking)?'<span class="cancellation-badge">Awaiting owner review</span>':''}</div>${history.map(item=>`<div class="cancellation-record"><div class="cancellation-record-top"><strong>${{pending:'Requested',approved:'Approved',declined:'Declined'}[item.status]||esc(item.status)}</strong><time datetime="${esc(item.created_at)}">${esc(date(item.created_at))}</time></div><p><strong>Customer’s reason:</strong> <span>${esc(item.reason)}</span></p>${item.decision_note?`<p><strong>GoRide’s reply:</strong> <span>${esc(item.decision_note)}</span></p><small>Decision ${esc(date(item.decision_at))}</small>`:''}${item.status==='pending'?`<p class="cancellation-help">The booking remains ${booking.status==='confirmed'?'accepted and reserved':'requested'} until the owner approves cancellation.</p>${owner?`<div class="decision-actions"><button type="button" class="primary" data-cancel-response="approved" data-cancel-booking="${esc(booking.id)}" data-cancel-id="${esc(item.id)}">Approve cancellation</button><button type="button" class="secondary" data-cancel-response="declined" data-cancel-booking="${esc(booking.id)}" data-cancel-id="${esc(item.id)}">Decline cancellation</button></div>`:''}`:''}</div>`).join('')}${active&&!pending(booking)&&!owner?`<p class="cancellation-help">Need to change your plans? Send a cancellation request for owner review.</p><button class="secondary" type="button" data-request-cancellation="${esc(booking.id)}">Request cancellation</button>`:''}<p class="cancellation-help">Applicable charges or refunds must be confirmed separately under your agreed <a href="/cancellation">cancellation policy</a>. This action does not process a payment or refund.</p></section>`;
}};
})();
